visual.raw:
const rows = (ctx.data && ctx.data.objects) || [];
const counter = {};
const order = [];
rows.forEach(function (r) {
  const raw = (r['option_selected'] !== undefined) ? r['option_selected'] : r['optionSelected'];
  const name = (raw === null || raw === undefined || raw === '') ? '未填写' : String(raw);
  const v = (r['voteCount'] !== undefined && r['voteCount'] !== null) ? Number(r['voteCount']) : 1;
  if (!(name in counter)) { counter[name] = 0; order.push(name); }
  counter[name] += v;
});
order.sort(function (a, b) { return counter[b] - counter[a]; });
return {
  tooltip: { trigger: 'axis' },
  legend: { bottom: 0 },
  grid: { left: 16, right: 16, top: 32, bottom: 48, containLabel: true },
  xAxis: { type: 'category', data: order, axisLabel: { interval: 0 } },
  yAxis: { type: 'value', minInterval: 1 },
  series: [
    {
      type: 'bar',
      name: '投票数',
      data: order.map(function (n) { return counter[n]; }),
      barMaxWidth: 40,
      label: { show: true, position: 'top' }
    }
  ]
};
